import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2020-04-16 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-04-16 -- Ceph Performance Meeting","date":"2020-04-16T00:00:00.000Z","updated":"2020-04-29T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-16_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-04-16_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-04-16_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,_,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新PR讨论</strong></p><ul><li>Igor提交了两个新PR： <ul><li>将Metallic Size和BlueStore切换回4K用于硬盘，基于其在混合分配器上的出色工作。</li><li>延迟大写入PR，该PR看起来很有前景。</li></ul></li><li>Ygritte确认大差异PR已默认启用，但混合分配器尚未默认启用，计划尽快完成。</li></ul></li><li><p><strong>性能优化</strong></p><ul><li>讨论了一个新的PR，该PR借鉴了几年前在文件存储中使用的前置分割方案，旨在通过预分割目录来提高大型目录的性能。</li><li>Nihad将平衡器和up matt模式默认开启，以便在下一个发布周期中进行更多测试。</li><li>Keith正在审查一个关于NVMe设备的PR，尚未有实质性进展。</li></ul></li><li><p><strong>性能测试</strong></p><ul><li>Mahan和Peng进行了一些关于单线程和双线程每分片的测试，发现单线程在高Q深度下的随机读性能显著提高。</li><li>讨论了是否应该从双线程每分片切换到单线程每分片，以及如何通过分析锁争用等问题来优化性能。</li></ul></li><li><p><strong>其他更新</strong></p><ul><li>Igor的两个PR（混合分配器和大写入）已合并。</li><li>讨论了增加Jenkins测试以捕获性能回归的可能性。</li><li>Adams的PR通过了最近的测试轮次，预计很快会合并。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认将大差异PR默认启用，并计划尽快将混合分配器也默认启用。</li><li>同意增加Jenkins测试以捕获性能回归，并可能调整测试参数以提高准确性。</li><li>决定继续探索单线程每分片的性能优势，并通过进一步的测试和分析来确定最佳配置。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Igor将完成混合分配器的默认启用更改，并提交PR。</li><li>Mahan和Peng将继续进行单线程和双线程每分片的性能测试，并提供详细的性能分析。</li><li>继续推进Adams的PR合并进程，以解决相关的性能瓶颈问题。</li><li>探索和实施更广泛的性能测试策略，包括在更大的集群环境中进行测试。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>会议中还讨论了其他一些PR的更新和关闭情况，但没有重大决策或行动计划。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议主要围绕Ceph的性能优化和测试展开，确认了一些关键的PR合并和默认启用计划，并制定了进一步的性能测试和分析计划。所有参与者将在接下来的周期中继续推进这些工作。</p>',11)])])}const c=l(r,[["render",o]]);export{p as __pageData,c as default};
